DROP TABLE IF EXISTS survey;

CREATE TABLE survey ( 
    customer_id VARCHAR(50),
    email VARCHAR(50),
    phone VARCHAR(50),
    address VARCHAR(50),
    rewards_member VARCHAR(50),
    survey_date VARCHAR(50),
    survey_time VARCHAR(50),
    satisfaction_rating VARCHAR(50),
    service_feedback VARCHAR(50),
    product_quality VARCHAR(50),
    visit_frequency VARCHAR(50),
    recommend_to_friend VARCHAR(50),
    freetext_response VARCHAR(50)
); 


